questions.solution:
const ALLOWED = ["title", "done"];

function taskChanges(body) {
  const unknown = Object.keys(body).filter((key) => !ALLOWED.includes(key));
  if (unknown.length > 0) return { status: 400, unknown };
  const changes = {};
  for (const key of ALLOWED) {
    if (key in body) changes[key] = body[key];
  }
  return { status: 200, changes };
}

console.log(taskChanges({ done: true }));
console.log(taskChanges({ done: true, owner_id: "mallory" }));
console.log(taskChanges({ title: "Buy oat milk", is_admin: true, id: 9 }));

