function attachmentKey(taskId, fileName, id) {
  if (!Number.isSafeInteger(taskId) || taskId < 1) {
    throw new RangeError("taskId must be a positive whole number");
  }
  return { key: `tasks/${taskId}/${id}`, metadata: { fileName: fileName.slice(0, 200) } };
}

