class TaskStore {
  highestFence = 0;
  title = "Buy milk";

  save(title, fence) {
    if (fence < this.highestFence) {
      throw new Error(`stale fence ${fence}, current is ${this.highestFence}`);
    }
    this.highestFence = fence;
    this.title = title;
  }
}

const store = new TaskStore();
store.save("Buy oat milk", 2);
try {
  store.save("Buy cow milk", 1);
} catch (error) {
  console.log(error.message);
}
store.save("Buy soy milk", 3);
