let nextFence = 1;
const locks = {
  async acquire(key) {
    console.log("acquire", key);
    return { fence: nextFence++, release: async () => console.log("release", key) };
  },
};

async function withLock(locks, key, work) {
  const lock = await locks.acquire(key);
  try {
    return await work(lock.fence);
  } finally {
    await lock.release();
  }
}

console.log(await withLock(locks, "task:1", async (fence) => `saved with fence ${fence}`));
try {
  await withLock(locks, "task:2", async () => {
    throw new Error("work failed");
  });
