function healthResponse(components) {
  const failing = components.filter((c) => !c.healthy).map((c) => c.name);
  if (failing.length === 0) return { status: 200, body: { healthy: true } };
  return { status: 503, body: { healthy: false, failing } };
}

console.log(healthResponse([
  { name: "database", healthy: true, status: "connected" },
  { name: "files", healthy: true, status: "ok" },
]));
